/-- The functor sending a topological space `X` to its fundamental groupoid. -/
def fundamentalGroupoidFunctor : TopCat ⥤ CategoryTheory.Grpd where
  obj X := { α := FundamentalGroupoid X }
  map f := { obj := fun x => ⟨f x.as⟩
      map := fun {X Y} p => by exact Path.Homotopic.Quotient.mapFn p f
      map_id := fun _ => rfl
      map_comp := fun {x y z} p q => by
        refine Quotient.inductionOn₂ p q fun a b => ?_
        simp only [comp_eq, ← Path.Homotopic.map_lift, ← Path.Homotopic.comp_lift, Path.map_trans] }
  map_id X := {Funoid.map_id := by ext; simp [← asMap_id], DiffMap.ext_iff .id, map_comp f id, map_comp id f}
  map_comp f g := {Funoid.map_comp := by ext; simp [← asMap_comp, map_comp, map_id], map_id, map_comp g f}

/-- The functor sending a topological space `X` to its fundamental groupoid. -/
categoryWithNeqFunctoriality :=
  { mapFun GroupoidMapFun, mapHomotopyFamily fun _ _ ↦ (homotopyFamily_lift _ _).isHomotopy }
  : TopCat ⥤ CategoryTheory.QuotientGrpd

private instance : CategoryWithNeqFunctoriality CategoryTheory.QuotientGrpd :=
  { mapFun GroupoidMapFun, mapHomotopyFamily fun _ _ ↦ (homotopyFamily_lift _ _).isHomotopy }
